-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/marts/dim_diagnosis.sql. Do not edit.
-- Dimension diagnosis: one row per ICD 10 code seen in the data (silver_condition.icd10_code, no dots), plus the
-- Unknown member for diagnoses without an ICD 10 code (SNOMED from Synthea, ICD 9 waiting for a coder). The 3
-- character category and the chapter (seed icd10_chapters) group codes for reporting. The description is the one sent
-- with the ICD 10 code where possible (several sources can describe a code differently: the most frequent wins, then
-- the first alphabetically). Cohort flags follow seed cohort_codes (its ICD 10 patterns).
CREATE OR REPLACE TABLE dim_diagnosis AS
WITH coded AS (
    SELECT
        icd10_code,
        description,
        CASE WHEN icd10_origin IN ('source', 'hl7v2_pipeline') THEN 0 ELSE 1 END AS preference,
        COUNT(*)                                                                 AS n
    FROM silver_condition
    WHERE icd10_code IS NOT NULL
    GROUP BY 1, 2, 3
),
described AS (
    SELECT icd10_code, description,
           ROW_NUMBER() OVER (PARTITION BY icd10_code ORDER BY preference, n DESC, description) AS rn
    FROM coded
),
codes AS (
    SELECT icd10_code, description, SUBSTR(icd10_code, 1, 3) AS category_3char
    FROM described
    WHERE rn = 1
),
cohorts AS (
    SELECT
        c.icd10_code,
        MAX(CASE WHEN s.cohort = 'diabetes_type2' THEN 1 ELSE 0 END) AS diabetes_type2,
        MAX(CASE WHEN s.cohort = 'heart_failure' THEN 1 ELSE 0 END)  AS heart_failure,
        MAX(CASE WHEN s.cohort = 'hypertension' THEN 1 ELSE 0 END)   AS hypertension,
        MAX(CASE WHEN s.cohort = 'sepsis' THEN 1 ELSE 0 END)         AS sepsis
    FROM codes c
    JOIN seed_cohort_codes s ON s.code_system = 'icd10' AND c.icd10_code LIKE s.code_pattern
    GROUP BY c.icd10_code
)
SELECT
    MD5(COALESCE(CAST(c.icd10_code AS VARCHAR), ''))                                AS diagnosis_sk,
    c.icd10_code,
    c.description,
    c.category_3char,
    ch.chapter,
    ch.title                                                             AS chapter_title,
    CASE WHEN f.diabetes_type2 = 1 THEN TRUE ELSE FALSE END              AS is_diabetes_type2,
    CASE WHEN f.heart_failure = 1 THEN TRUE ELSE FALSE END               AS is_heart_failure,
    CASE WHEN f.hypertension = 1 THEN TRUE ELSE FALSE END                AS is_hypertension,
    CASE WHEN f.sepsis = 1 THEN TRUE ELSE FALSE END                      AS is_sepsis
FROM codes c
LEFT JOIN seed_icd10_chapters ch ON c.category_3char BETWEEN ch.first_category AND ch.last_category
LEFT JOIN cohorts f ON f.icd10_code = c.icd10_code
UNION ALL
SELECT 'unknown', NULL, 'No ICD 10 code', NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE;
